"use client"
import { useState } from "react"
import { createClient } from "@/lib/supabase/client"
import { useRouter } from "next/navigation"

const SYNTECH_LOGO = "data:image/png;base64,"
const FOYNES_LOGO = "data:image/png;base64,"

export default function LoginPage() {
  const [email, setEmail] = useState("")
  const [password, setPassword] = useState("")
  const [error, setError] = useState("")
  const [loading, setLoading] = useState(false)
  const router = useRouter()
  const supabase = createClient()

  async function handleLogin(e: React.FormEvent) {
    e.preventDefault()
    setLoading(true); setError("")
    const { error } = await supabase.auth.signInWithPassword({ email, password })
    if (error) { setError("Incorrect email or password"); setLoading(false); return }
    window.location.href = "/dashboard"
  }

  return (
    <div style={{ minHeight:"100vh", background:"linear-gradient(135deg,#081A2E 0%,#0E2A47 60%,#0a1f38 100%)", display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", padding:24, position:"relative", overflow:"hidden", fontFamily:"Inter,-apple-system,sans-serif" }}>
      <div style={{ position:"absolute", inset:0, pointerEvents:"none", backgroundImage:"repeating-linear-gradient(90deg,transparent 0,transparent 59px,rgba(255,255,255,0.025) 59px,rgba(255,255,255,0.025) 60px),repeating-linear-gradient(0deg,transparent 0,transparent 59px,rgba(255,255,255,0.025) 59px,rgba(255,255,255,0.025) 60px)" }} />
      <div style={{ position:"absolute", top:0, left:0, right:0, height:3, background:"#E63946" }} />
      <div style={{ display:"flex", alignItems:"center", gap:24, marginBottom:48, position:"relative", zIndex:1 }}>
        <img src={SYNTECH_LOGO} alt="Syntech" style={{ height:44, width:"auto" }} />
        <span style={{ color:"rgba(255,255,255,0.25)", fontSize:22, fontWeight:200 }}>x</span>
        <img src={FOYNES_LOGO} alt="Foynes Engineering" style={{ height:38, width:"auto", background:"white", padding:"3px 8px", borderRadius:3 }} />
      </div>
      <div style={{ width:"100%", maxWidth:420, position:"relative", zIndex:1, background:"white", boxShadow:"0 32px 80px rgba(0,0,0,0.5)" }}>
        <div style={{ background:"#0E2A47", padding:"24px 32px", borderBottom:"3px solid #E63946" }}>
          <div style={{ fontSize:11, letterSpacing:"0.28em", textTransform:"uppercase", color:"rgba(255,255,255,0.5)", fontWeight:600, marginBottom:6 }}>Applicant Tracking System</div>
          <div style={{ fontSize:22, fontWeight:700, color:"white", letterSpacing:"-0.02em" }}>Sign in to ATS Portal</div>
        </div>
        <div style={{ padding:"32px 32px 28px" }}>
          <form onSubmit={handleLogin}>
            <div style={{ marginBottom:20 }}>
              <label style={{ display:"block", fontSize:10, letterSpacing:"0.18em", textTransform:"uppercase", color:"#4A5E78", fontWeight:600, marginBottom:8 }}>Email address</label>
              <input type="email" value={email} onChange={e=>setEmail(e.target.value)} required placeholder="you@email.com" autoComplete="email"
                style={{ width:"100%", padding:"12px 16px", border:"1px solid #D5DCE5", background:"#F4F6F9", fontSize:14, color:"#0E2A47", outline:"none", fontFamily:"inherit", boxSizing:"border-box" }} />
            </div>
            <div style={{ marginBottom:24 }}>
              <label style={{ display:"block", fontSize:10, letterSpacing:"0.18em", textTransform:"uppercase", color:"#4A5E78", fontWeight:600, marginBottom:8 }}>Password</label>
              <input type="password" value={password} onChange={e=>setPassword(e.target.value)} required placeholder="••••••••" autoComplete="current-password"
                style={{ width:"100%", padding:"12px 16px", border:"1px solid #D5DCE5", background:"#F4F6F9", fontSize:14, color:"#0E2A47", outline:"none", fontFamily:"inherit", boxSizing:"border-box" }} />
            </div>
            {error && <div style={{ marginBottom:16, padding:"12px 16px", background:"rgba(230,57,70,0.06)", borderLeft:"3px solid #E63946", fontSize:13, color:"#B7202E" }}>{error}</div>}
            <button type="submit" disabled={loading}
              style={{ width:"100%", padding:"14px 24px", background:"#0E2A47", color:"white", border:"none", cursor:"pointer", fontSize:11, fontWeight:700, letterSpacing:"0.2em", textTransform:"uppercase", fontFamily:"inherit" }}>
              {loading ? "Signing in..." : "SIGN IN"}
            </button>
          </form>
        </div>
        <div style={{ padding:"16px 32px 20px", borderTop:"1px solid #E8EDF3", background:"#F4F6F9", fontSize:12, color:"#8A99AE", textAlign:"center" }}>
          Access issues? <a href="mailto:stephen@syntechrecruitment.co.uk" style={{ color:"#0E2A47", fontWeight:600, textDecoration:"none" }}>stephen@syntechrecruitment.co.uk</a>
        </div>
      </div>
      <div style={{ marginTop:36, fontSize:10, color:"rgba(255,255,255,0.2)", letterSpacing:"0.18em", textTransform:"uppercase", textAlign:"center", position:"relative", zIndex:1 }}>
        Built by Legatum Group for Syntech Recruitment
      </div>
    </div>
  )
}